def initial_content(name):
    suffix = Path(name).suffix
    if name == '.gitignore':
        return 'node_modules/\ndist/\n.env\n.env.*\n!.env.example\n.dev.vars\ncoverage/\nplaywright-report/\ntest-results/\n.DS_Store\n'
    if name == 'README.md':
        return '# NEURON\n\nStatus: architecture scaffold, not an implemented application.\n\nEvery planned file has been created. Implement and test each module before use.\nSee ARCHITECTURE.md and docs/implementation-roadmap.md.\n'
    if name.endswith('package.json'):
        parent = Path(name).parent.as_posix()
        label = 'neuron' if parent == '.' else '@neuron/' + parent.split('/')[-1]
        return json.dumps({'name':label, 'version':'0.0.0', 'private':True, 'type':'module'}, indent=2)+'\n'
    if name == 'pnpm-workspace.yaml':
        return 'packages:\n  - "apps/*"\n  - "packages/*"\n  - "services/*"\n'
    if suffix in ('.ts', '.tsx', '.mjs'):
        return '// PLANNED MODULE: '+name+'\n// Not implemented. See the architecture and acceptance criteria.\nexport {};\n'
    if suffix == '.json': return '{}\n'
    if suffix == '.md': return '# '+Path(name).stem.replace('-', ' ').title()+'\n\nPlanned document. Not yet implemented.\n'
    if suffix in ('.yaml','.yml','.toml') or Path(name).name.startswith('.'):
        return '# Planned configuration: '+name+'\n'
    if suffix == '.css': return '/* Planned stylesheet: '+name+' */\n'
    if suffix in ('.html','.svg','.webmanifest'): return ''
    return ''

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root',default='neuron')
    args=parser.parse_args()
    root=Path(args.root).expanduser().resolve()
    # Refuse existing files before writing anything: never silently overwrite work.
    collisions=[p for p in FILES if (root/p).exists()]
    blocked=[p for p in FILES if any(x.exists() and not x.is_dir() for x in (root/p).parents)]
    if collisions or blocked:
        parser.error('No files written. Existing paths conflict: '+', '.join((collisions+blocked)[:10]))
    root.mkdir(parents=True,exist_ok=True)
    for name in FILES:
        dest=root/name
        dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_text(initial_content(name),encoding='utf-8')
    missing=[p for p in FILES if not (root/p).is_file()]
    if missing: raise SystemExit('Verification failed: '+str(missing))
    print(f'Created and verified {len(FILES)} planned files in {root}')
    print('Scaffold only: no application features or dependencies have been implemented yet.')

if __name__=='__main__': main()